import type { FinancialRequirementItem } from "@/app/types/checklist";
import { ExplainWithDalilButton } from "@/components/chat/explain-with-dalil-button";
import { compactFacts, fact } from "@/lib/explanation-context";

// GOA-035 AC: "Financial Requirements are rendered only from structured backend
// data (never generated by the frontend or an LLM)". Every field below is read
// verbatim from FinancialRequirementsResponse (services/rag/app/api/checklists.py's
// /financial route, sourced from GOA-108's visa_requirements.proof_of_funds) — this
// component computes nothing and has no fallback text that could be mistaken for
// backend data. If the caller has no items for this program's country, it renders
// nothing at all (see ChecklistView), satisfying "omit if backend has no supported
// visa data" rather than showing an empty heading.
export default function FinancialRequirements({
  items,
  programId,
  programName,
}: {
  items: FinancialRequirementItem[];
  programId?: string;
  programName?: string;
}) {
  if (items.length === 0) {
    return null;
  }

  return (
    <section
      data-testid="checklist-phase"
      data-phase="Financial Requirements"
      className="print-avoid-break"
    >
      <h3 className="text-sm font-semibold text-brand-fg mb-2">
        Financial Requirements
      </h3>
      <ul className="space-y-2">
        {items.map((item, index) => (
          <li
            key={`${item.country}-${item.issuingBody}-${index}`}
            data-testid="financial-item"
            className="rounded-xl border border-border bg-surface p-3"
          >
            <div className="flex items-start justify-between gap-3">
              <p className="text-sm font-medium text-brand-fg">
                {item.country} — {item.issuingBody}
              </p>
              <ExplainWithDalilButton
                context={{
                  kind: "visa_requirement",
                  title: `${item.country} financial requirement`,
                  subjectId: programId,
                  summary: programName,
                  facts: compactFacts([
                    fact("Country", item.country, item.sourceUrl),
                    fact("Issuing body", item.issuingBody, item.sourceUrl),
                    fact("Requirement", item.message, item.sourceUrl),
                    fact("Last verified", item.lastVerifiedAt, item.sourceUrl),
                  ]),
                  limitations: [
                    "Financial and visa requirements can change; verify the official source before applying.",
                  ],
                }}
                prompt={`Explain this financial requirement for ${item.country}: “${item.message}”. What does it mean in practice, and what must I confirm with ${item.issuingBody}?`}
              />
            </div>
            <p className="mt-0.5 text-xs text-fg-muted">{item.message}</p>
            <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] text-fg-subtle">
              {item.lastVerifiedAt && (
                <span>
                  Last verified {new Date(item.lastVerifiedAt).toLocaleDateString()}
                </span>
              )}
              {item.sourceUrl && (
                <a
                  href={item.sourceUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-brand-fg underline underline-offset-2 print:no-underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-muted rounded-xs"
                >
                  Official source
                </a>
              )}
            </div>
          </li>
        ))}
      </ul>
    </section>
  );
}
